import React, { useEffect, useState, useCallback } from 'react';
import { useParams } from 'react-router-dom';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { scykRoutes } from '../../config/scykRoutes';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchMedicalIncidentById,
  createMedicalIncident,
  updateMedicalIncident,
  setSelectedIncident,
  startIncidentAnalysis,
  submitIncidentAnalysis,
  submitIncidentFeedback,
  toggleIncidentServiceMismatch,
  toggleIncidentNotMedical,
  saveIncidentStaffAnalysis,
  saveIncidentManagementAnalysis,
} from '../../store/slices/medicalIncidentsSlice';
import { addToast } from '../../store/slices/uiSlice';
import { ChatTab, IncidentPrintModal } from '../../components/shared';
import { Tab1IncidentInfo } from './components/Tab1_IncidentInfo';
import { Tab4AStaffAnalysis } from './components/Tab4A_StaffAnalysis';
import type { IncidentSubjects } from './components/Tab4A_StaffAnalysis';
import { Tab4BManagementAnalysis } from './components/Tab4B_ManagementAnalysis';
import { useMessages } from '../../hooks/useMessages';
import {
  MedicalIncident,
  IncidentStatus,
  StaffAnalysis,
  ManagementAnalysis,
  createEmptyMedicalIncident,
  createEmptyIncidentTypeGroups,
  createEmptyCauseGroups,
} from '../../models/MedicalIncident';
import { resolveIncidentFormHint } from './incidentFormStatusHint';
import type { IncidentFormTabId } from './incidentFormStatusHint';
import { useMedicalIncidentPermissions } from '../../hooks/useMedicalIncidentPermissions';
import styles from './MedicalIncidentFormPage.module.css';
import {
  ValidationErrors,
  ValidationRule,
  runValidation,
  scrollToFirstErrorSection,
  clearFieldErrors,
} from '../../utils/formValidation';
import { nowAsISOWithOffset } from '../../utils/dateTime';

// ─── Validation rules ──────────────────────────────────────────────────────
//
// Rules are declared in DOM top-to-bottom section order so that
// scrollToFirstErrorSection always jumps to the topmost visible error.
//
import { Button, Tabs, LeaveConfirmModal } from '@linm-soft-org/linm-web-common-components';
import {
  useFormLeaveGuard,
  runWithLeaveGuard,
} from '@linm-soft-org/linm-web-common-components';
function buildIncidentRules(isDraft: boolean): ValidationRule<MedicalIncident>[] {
  return [
    // ── Patient section (DOM first) ──────────────────────────────────────
    {
      field:     'patientName',
      sectionId: 'field-section-patient',
      validate:  (f) =>
        f.patientName && f.patientName.length > 200
          ? 'Họ tên bệnh nhân không được vượt quá 200 ký tự'
          : null,
    },
    // ── Report section ───────────────────────────────────────────────────
    // (incidentName is now optional)
    {
      field:     'occurredAt',
      sectionId: 'field-section-report',
      validate:  (f) =>
        !isDraft && !f.occurredAt
          ? 'Thời gian xảy ra là bắt buộc khi gửi báo cáo'
          : null,
    },
    // ── Incident subject section ─────────────────────────────────────────
    {
      field:     'subjectPatient',
      sectionId: 'field-section-incident-subject',
      validate:  (f) =>
        !isDraft && !f.subjectPatient && !f.subjectStaff && !f.subjectVisitor && !f.subjectEquipment
          ? 'Vui lòng chọn ít nhất một đối tượng xảy ra sự cố'
          : null,
    },
    // ── Locations section ─────────────────────────────────────────────────
    {
      field:     'incidentDepartmentLocation',
      sectionId: 'field-section-locations',
      validate:  (f) =>
        !isDraft && !f.incidentDepartmentLocation?.trim()
          ? 'Khoa/phòng/vị trí xảy ra sự cố là bắt buộc khi gửi báo cáo'
          : null,
    },
    {
      field:     'specificLocation',
      sectionId: 'field-section-locations',
      validate:  (f) =>
        !isDraft && !f.specificLocation?.trim()
          ? 'Vị trí cụ thể là bắt buộc khi gửi báo cáo'
          : null,
    },
    // ── Notifications section ────────────────────────────────────────────
    {
      field:     'notifyDoctor',
      sectionId: 'field-section-notifications',
      validate:  (f) =>
        !isDraft && !f.notifyDoctor
          ? 'Thông báo cho Bác sĩ điều trị là bắt buộc khi gửi báo cáo'
          : null,
    },
    {
      field:     'recordInMedicalRecord',
      sectionId: 'field-section-notifications',
      validate:  (f) =>
        !isDraft && !f.recordInMedicalRecord
          ? 'Ghi nhận vào hồ sơ bệnh án là bắt buộc khi gửi báo cáo'
          : null,
    },
    {
      field:     'notifyFamily',
      sectionId: 'field-section-notifications',
      validate:  (f) =>
        !isDraft && !f.notifyFamily
          ? 'Thông báo cho người nhà là bắt buộc khi gửi báo cáo'
          : null,
    },
    {
      field:     'notifyPatient',
      sectionId: 'field-section-notifications',
      validate:  (f) =>
        !isDraft && !f.notifyPatient
          ? 'Thông báo cho người bệnh là bắt buộc khi gửi báo cáo'
          : null,
    },
    // ── Classification section ───────────────────────────────────────────
    {
      field:     'occurrenceStatus',
      sectionId: 'field-section-classification',
      validate:  (f) =>
        !isDraft && !f.occurrenceStatus
          ? 'Phân loại ban đầu về sự cố là bắt buộc khi gửi báo cáo'
          : null,
    },
    {
      field:     'severity',
      sectionId: 'field-section-classification',
      validate:  (f) =>
        !isDraft && !f.severity
          ? 'Mức độ ảnh hưởng là bắt buộc khi gửi báo cáo'
          : null,
    },
    // ── Reporter type section ─────────────────────────────────────────────
    {
      field:     'reporterIsNurse',
      sectionId: 'field-section-reporter',
      validate:  (f) =>
        !isDraft &&
        !f.reporterIsNurse && !f.reporterIsPatient && !f.reporterIsVisitor &&
        !f.reporterIsDoctor && !f.reporterIsOther
          ? 'Vui lòng chọn ít nhất một chức danh người thông báo'
          : null,
    },
    // ── Description section ──────────────────────────────────────────────
    {
      field:     'briefDescription',
      sectionId: 'field-section-description',
      validate:  (f) =>
        !isDraft && !f.briefDescription?.trim()
          ? 'Mô tả sự cố là bắt buộc khi gửi báo cáo'
          : null,
    },
    {
      field:     'initialSolution',
      sectionId: 'field-section-description',
      validate:  (f) =>
        !isDraft && !f.initialSolution?.trim()
          ? 'Đề xuất giải pháp ban đầu là bắt buộc khi gửi báo cáo'
          : null,
    },
    {
      field:     'initialTreatment',
      sectionId: 'field-section-description',
      validate:  (f) =>
        !isDraft && !f.initialTreatment?.trim()
          ? 'Điều trị/xử trí ban đầu là bắt buộc khi gửi báo cáo'
          : null,
    },
  ];
}
const enum TabIds {
  Incident           = 'incident',
  StaffAnalysis      = 'staff_analysis',
  ManagementAnalysis = 'management_analysis',
  Chat               = 'chat',
  Documents          = 'documents',
}
// ─── Defaults ──────────────────────────────────────────────────────────────

const defaultStaffAnalysis = (): StaffAnalysis => ({
  detailedDescription: '',
  affectedSubjects: '',
  incidentLocation: '',
  incidentTypeGroups: createEmptyIncidentTypeGroups(),
  treatmentOrders: '',
  causeGroups: createEmptyCauseGroups(),
  correctiveActions: '',
  preventionRecommendations: '',
});

const defaultManagementAnalysis = (): ManagementAnalysis => ({
  // Section I
  findingsSummary:                '',
  discussedWithReporter:          undefined,
  matchesOfficialRecommendations: undefined,
  specificRecommendations:        '',
  // Section II – on patient
  injurySeverityPatient:          '',
  // Section II – on organization
  injuryOrgPropertyDamage:        false,
  injuryOrgIncreasedResources:    false,
  injuryOrgMediaAttention:        false,
  injuryOrgPatientComplaint:      false,
  injuryOrgReputationDamage:      false,
  injuryOrgLegalIntervention:     false,
  injuryOrgOther:                 false,
  // Analysis
  rootCauseAnalysis:              '',
  correctiveActions:              '',
  preventiveActions:              '',
  recommendations:                '',
  expertEmail:                    '',
  // Sign-off
  analysedById:                   '',
  analysedByCode:                 '',
  analysedBy:                     '',
  leaderTitle:                    '',
  analysisDate:                   null,
  analysisTime:                   '',
});

/**
 * Deep-merge a loaded StaffAnalysis with defaults so that any field that is
 * missing from older/partial stored JSON falls back to a safe initial value.
 */
function mergeStaffAnalysis(loaded: StaffAnalysis | null): StaffAnalysis {
  const def      = defaultStaffAnalysis();
  if (!loaded) return def;
  const defG = def.incidentTypeGroups;
  const defC = def.causeGroups;
  return {
    ...def,
    ...loaded,
    incidentTypeGroups: {
      group1:  { ...defG.group1,  ...loaded.incidentTypeGroups?.group1  },
      group2:  { ...defG.group2,  ...loaded.incidentTypeGroups?.group2  },
      group3:  { ...defG.group3,  ...loaded.incidentTypeGroups?.group3  },
      group4:  { ...defG.group4,  ...loaded.incidentTypeGroups?.group4  },
      group5:  { ...defG.group5,  ...loaded.incidentTypeGroups?.group5  },
      group6:  { ...defG.group6,  ...loaded.incidentTypeGroups?.group6  },
      group7:  { ...defG.group7,  ...loaded.incidentTypeGroups?.group7  },
      group8:  { ...defG.group8,  ...loaded.incidentTypeGroups?.group8  },
      group9:  { ...defG.group9,  ...loaded.incidentTypeGroups?.group9  },
      group10: { ...defG.group10, ...loaded.incidentTypeGroups?.group10 },
      group11: { ...defG.group11, ...loaded.incidentTypeGroups?.group11 },
    },
    causeGroups: {
      group1: { ...defC.group1, ...loaded.causeGroups?.group1 },
      group2: { ...defC.group2, ...loaded.causeGroups?.group2 },
      group3: { ...defC.group3, ...loaded.causeGroups?.group3 },
      group4: { ...defC.group4, ...loaded.causeGroups?.group4 },
      group5: { ...defC.group5, ...loaded.causeGroups?.group5 },
      group6: { ...defC.group6, ...loaded.causeGroups?.group6 },
    },
  };
}

/**
 * Deep-merge a loaded ManagementAnalysis with defaults.
 */
function mergeManagementAnalysis(loaded: ManagementAnalysis | null): ManagementAnalysis {
  return { ...defaultManagementAnalysis(), ...loaded };
}

// ─── Component ─────────────────────────────────────────────────────────────

const MedicalIncidentFormPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const appNavigate = useAppNavigate();
  const dispatch   = useAppDispatch();
  const isNew      = !id || id === 'new';

  const { selectedIncident, saving, loading } = useAppSelector((s) => s.medicalIncidents);
  const authUser = useAppSelector((s) => s.auth.user);
  const {
    canCreate,
    canSaveDraft,
    canSubmitReport,
    canStartAnalysis,
    canSaveAnalysis,
    canCompleteAnalysis,
    canEditWhenComplete,
    canToggleMismatch,
    canToggleNotMedical,
    canPrint,
  } = useMedicalIncidentPermissions();

  const [activeTab, setActiveTab] = useState<TabIds>(TabIds.Incident);
  const [form, setForm] = useState<Partial<MedicalIncident>>({});
  const [validationErrors, setValidationErrors] = useState<ValidationErrors>({});
  const [staffAnalysisErrors, setStaffAnalysisErrors] = useState<Record<string, string>>({});
  const [managementAnalysisErrors, setManagementAnalysisErrors] = useState<Record<string, string>>({});
  const [bannerCollapsed, setBannerCollapsed] = useState(false);
  const [staffAnalysisDirty, setStaffAnalysisDirty] = useState(false);
  const [managementAnalysisDirty, setManagementAnalysisDirty] = useState(false);
  const [formDirty, setFormDirty] = useState(false);
  const [staffBannerCollapsed, setStaffBannerCollapsed] = useState(false);
  const [managementBannerCollapsed, setManagementBannerCollapsed] = useState(false);

  const anyDirty = formDirty || staffAnalysisDirty || managementAnalysisDirty;

  const clearLeaveState = useCallback(() => {
    setFormDirty(false);
    setStaffAnalysisDirty(false);
    setManagementAnalysisDirty(false);
    setValidationErrors({});
    setStaffAnalysisErrors({});
    setManagementAnalysisErrors({});
    setBannerCollapsed(false);
    setStaffBannerCollapsed(false);
    setManagementBannerCollapsed(false);
  }, []);

  const { guardedNavigate, leaveConfirmModalProps } = useFormLeaveGuard({
    isDirty: anyDirty,
    onBeforeLeave: clearLeaveState,
    title: 'Bạn có dữ liệu chưa lưu',
    message: 'Tất cả thay đổi chưa được lưu sẽ bị mất. Bạn có chắc muốn rời khỏi trang này không?',
    stayLabel: 'Ở lại trang',
    leaveLabel: 'Rời khỏi trang',
  });

  const [printModalOpen, setPrintModalOpen] = useState(false);

  // Staff feedback state
  const [feedbackRating,  setFeedbackRating]  = useState(0);
  const [feedbackText,    setFeedbackText]    = useState('');
  const [feedbackOpen,    setFeedbackOpen]    = useState(false);

  // Unified chat messages (only active when incident exists)
  const {
    chatMessages,
    sendMessage,
    chatCount,
    hasMoreChat,
    loadMoreChat,
    loading: chatLoading,
  } = useMessages('incident', !isNew ? id : undefined);

  // Load existing incident
  useEffect(() => {
    const timer = setTimeout(() => {
      if (!isNew && id) {
        dispatch(setSelectedIncident(null));
        dispatch(fetchMedicalIncidentById(id));
      } else {
        dispatch(setSelectedIncident(null));
      }
    }, 0);
    return () => clearTimeout(timer);
  }, [dispatch, id, isNew]);

  // Populate form from loaded incident or init new
  useEffect(() => {
    if (!isNew && selectedIncident && selectedIncident.id === id) {
      setForm({
        ...selectedIncident,
        staffAnalysis:      mergeStaffAnalysis(selectedIncident.staffAnalysis),
        managementAnalysis: mergeManagementAnalysis(selectedIncident.managementAnalysis),
      });
      setStaffAnalysisDirty(false);
      setManagementAnalysisDirty(false);
      setFormDirty(false);
      setStaffBannerCollapsed(false);
      setManagementBannerCollapsed(false);
      setStaffAnalysisErrors({});
      setManagementAnalysisErrors({});
    } else if (isNew) {
      const now = nowAsISOWithOffset();
      setForm({
        ...createEmptyMedicalIncident(),
        createdAt: now,
        occurredAt: now,
        // All radio fields (notifyDoctor, severity, etc.) start as null — no default (factory already null)
        // reportedById/reportedByName start empty — optional, user picks via UserSearchInput
        staffAnalysis:      defaultStaffAnalysis(),
        managementAnalysis: defaultManagementAnalysis(),
      });
      setFormDirty(false);
      setStaffAnalysisDirty(false);
      setManagementAnalysisDirty(false);
      setValidationErrors({});
      setStaffAnalysisErrors({});
      setManagementAnalysisErrors({});
    }
  }, [isNew, selectedIncident, authUser, id]);

  const patch = (p: Partial<MedicalIncident>) => {
    setForm((prev) => ({ ...prev, ...p }));
    setValidationErrors((prev) => clearFieldErrors(prev, Object.keys(p)));
    // Analysis tabs track dirty via staffAnalysisDirty / managementAnalysisDirty only.
    const isAnalysisOnly = Object.keys(p).every(
      (k) => k === 'staffAnalysis' || k === 'managementAnalysis',
    );
    if (!isAnalysisOnly) {
      setFormDirty(true);
    }
  };

  const handleSave = async (asDraft = false) => {
    const rules  = buildIncidentRules(asDraft);
    const errors = runValidation(form, rules);

    if (Object.keys(errors).length > 0) {
      setValidationErrors(errors);
      setBannerCollapsed(false);
      // Switch to Tab 1 so the user can see the errors
      if (activeTab !== TabIds.Incident) {
        setActiveTab(TabIds.Incident);
      }
      scrollToFirstErrorSection(errors, rules);
      return;
    }

    setValidationErrors({});

    // Workflow-managed statuses (in_analysis, resolved, closed) must NOT be overwritten
    // by a general save.  Only draft ↔ submitted can be toggled here.
    // Transitions to/from in_analysis and resolved are done via dedicated action
    // endpoints (handleStartAnalysis / handleSubmitAnalysis).
    const workflowStatuses: IncidentStatus[] = [
      IncidentStatus.InAnalysis,
      IncidentStatus.Resolved,
      IncidentStatus.Closed,
    ];
    const targetStatus =
      form.status && workflowStatuses.includes(form.status)
        ? form.status                                              // preserve workflow state
        : asDraft ? IncidentStatus.Draft : IncidentStatus.Submitted; // normal draft/submit

    const data: Partial<MedicalIncident> = {
      ...form,
      status: targetStatus,
    };

    try {
      if (isNew) {
        await dispatch(createMedicalIncident(data)).unwrap();
        dispatch(addToast({ message: asDraft ? 'Lưu nháp sự cố y khoa thành công' : 'Tạo sự cố y khoa thành công', type: 'success' }));
        setFormDirty(false);
        appNavigate(scykRoutes.incidents.list, { replace: true });
      } else {
        await dispatch(updateMedicalIncident({ id: id!, data })).unwrap();
        dispatch(addToast({ message: 'Cập nhật sự cố y khoa thành công', type: 'success' }));
        setFormDirty(false);
      }
    } catch (error: unknown) {
      const message = error instanceof Error
        ? error.message
        : 'Đã có lỗi xảy ra, vui lòng thử lại';
      dispatch(addToast({ message, type: 'error' }));
    }
  };

  const handleBack = () => guardedNavigate(() => appNavigate(scykRoutes.incidents.list));

  // ── Action handlers (manager/staff workflows) ─────────────────────────────
  const handleStartAnalysis = async () => {
    if (!id) return;
    try {
      await dispatch(startIncidentAnalysis(id)).unwrap();
      dispatch(addToast({ message: 'Đã bắt đầu phân tích sự cố', type: 'success' }));
    } catch (error: unknown) {
      dispatch(addToast({ message: error instanceof Error ? error.message : 'Lỗi bắt đầu phân tích', type: 'error' }));
    }
  };

  const handleSubmitAnalysis = async () => {
    if (!id) return;
    // Validate both tabs before allowing completion
    const saErrors = validateStaffAnalysis(form.staffAnalysis);
    const maErrors = validateManagementAnalysis(form.managementAnalysis);
    if (Object.keys(saErrors).length > 0) {
      setStaffAnalysisErrors(saErrors);
      setManagementAnalysisErrors({});
      setStaffBannerCollapsed(false);
      setActiveTab(TabIds.StaffAnalysis);
      dispatch(addToast({ message: 'Vui lòng hoàn thành các trường bắt buộc trong tab Phân Tích Sự Cố', type: 'warning' }));
      return;
    }
    if (Object.keys(maErrors).length > 0) {
      setManagementAnalysisErrors(maErrors);
      setStaffAnalysisErrors({});
      setManagementBannerCollapsed(false);
      setActiveTab(TabIds.ManagementAnalysis);
      dispatch(addToast({ message: 'Vui lòng hoàn thành các trường bắt buộc trong tab Chuyên Gia Đánh Giá', type: 'warning' }));
      return;
    }
    try {
      await dispatch(submitIncidentAnalysis(id)).unwrap();
      dispatch(addToast({ message: 'Phân tích sự cố đã hoàn thành', type: 'success' }));
    } catch (error: unknown) {
      dispatch(addToast({ message: error instanceof Error ? error.message : 'Lỗi Đánh dấu hoàn thành', type: 'error' }));
    }
  };

  const handleToggleServiceMismatch = async () => {
    if (!id) return;
    const current = form.isServiceMismatch ?? false;
    try {
      await dispatch(toggleIncidentServiceMismatch({ id, isServiceMismatch: !current })).unwrap();
      dispatch(addToast({ message: !current ? 'Đã đánh dấu nhầm dịch vụ' : 'Đã bỏ đánh dấu nhầm dịch vụ', type: 'success' }));
    } catch (error: unknown) {
      dispatch(addToast({ message: error instanceof Error ? error.message : 'Lỗi cập nhật', type: 'error' }));
    }
  };

  const handleToggleNotMedicalIncident = async () => {
    if (!id) return;
    const current = form.isNotMedicalIncident ?? false;
    try {
      await dispatch(toggleIncidentNotMedical({ id, isNotMedicalIncident: !current })).unwrap();
      dispatch(addToast({
        message: !current ? 'Đã đánh dấu không thuộc sự cố y khoa' : 'Đã bỏ đánh dấu nhầm sự cố',
        type: 'success',
      }));
    } catch (error: unknown) {
      dispatch(addToast({ message: error instanceof Error ? error.message : 'Lỗi cập nhật', type: 'error' }));
    }
  };

  const handleSubmitFeedback = async () => {
    if (!id || feedbackRating < 1) {
      dispatch(addToast({ message: 'Vui lòng chọn số sao đánh giá (1-5)', type: 'warning' }));
      return;
    }
    try {
      await dispatch(submitIncidentFeedback({ id, rating: feedbackRating, feedback: feedbackText })).unwrap();
      dispatch(addToast({ message: 'Đã gửi đánh giá thành công', type: 'success' }));
      setFeedbackOpen(false);
    } catch (error: unknown) {
      dispatch(addToast({ message: error instanceof Error ? error.message : 'Lỗi gửi đánh giá', type: 'error' }));
    }
  };

  // ── Validate analysis required fields ────────────────────────────────────
  const validateStaffAnalysis = (sa: typeof form.staffAnalysis): Record<string, string> => {
    const errs: Record<string, string> = {};
    if (!sa) return errs;
    if (!sa.affectedSubjects?.trim()) errs.affectedSubjects = 'Đối tượng chịu ảnh hưởng là bắt buộc';
    if (!sa.incidentLocation?.trim()) {
      errs.incidentLocation = 'Khoa/phòng/vị trí xảy ra sự cố là bắt buộc';
    }
    return errs;
  };

  const validateManagementAnalysis = (ma: typeof form.managementAnalysis): Record<string, string> => {
    const errs: Record<string, string> = {};
    if (!ma) return errs;
    if (!ma.findingsSummary?.trim())    errs.findingsSummary    = 'Mô tả kết quả phát hiện là bắt buộc';
    if (!ma.discussedWithReporter)      errs.discussedWithReporter = 'Vui lòng chọn trạng thái thảo luận với người báo cáo';
    if (!ma.matchesOfficialRecommendations) errs.matchesOfficialRecommendations = 'Vui lòng chọn trạng thái phù hợp khuyến cáo';
    if (!ma.injurySeverityPatient?.trim()) errs.injurySeverityPatient = 'Mức độ tổn thương trên người bệnh là bắt buộc';
    if (!ma.rootCauseAnalysis?.trim()) errs.rootCauseAnalysis = 'Kết luận là bắt buộc';
    if (!ma.correctiveActions?.trim()) errs.correctiveActions  = 'Kết luận nguyên nhân gốc rễ là bắt buộc';
    if (!ma.analysedById?.trim())      errs.analysedById       = 'Người phân tích là bắt buộc';
    if (!ma.analysisDate?.trim())      errs.analysisDate       = 'Ngày phân tích là bắt buộc';
    return errs;
  };

  const saveStaffAnalysisSection = async (): Promise<boolean> => {
    if (!id || !staffAnalysisDirty) return true;
    const saErrors = validateStaffAnalysis(form.staffAnalysis);
    if (Object.keys(saErrors).length > 0) {
      setStaffAnalysisErrors(saErrors);
      dispatch(addToast({ message: 'Vui lòng điền đầy đủ các trường bắt buộc trước khi lưu', type: 'warning' }));
      return false;
    }
    setStaffAnalysisErrors({});
    try {
      await dispatch(saveIncidentStaffAnalysis({
        id,
        staffAnalysis: form.staffAnalysis!,
      })).unwrap();
      dispatch(addToast({ message: 'Đã lưu phân tích sự cố', type: 'success' }));
      setStaffAnalysisDirty(false);
      return true;
    } catch (error: unknown) {
      dispatch(addToast({ message: error instanceof Error ? error.message : 'Lỗi lưu phân tích', type: 'error' }));
      return false;
    }
  };

  const saveManagementAnalysisSection = async (): Promise<boolean> => {
    if (!id || !managementAnalysisDirty) return true;
    const maErrors = validateManagementAnalysis(form.managementAnalysis);
    if (Object.keys(maErrors).length > 0) {
      setManagementAnalysisErrors(maErrors);
      dispatch(addToast({ message: 'Vui lòng điền đầy đủ các trường bắt buộc trước khi lưu', type: 'warning' }));
      return false;
    }
    setManagementAnalysisErrors({});
    try {
      await dispatch(saveIncidentManagementAnalysis({ id, managementAnalysis: form.managementAnalysis! })).unwrap();
      dispatch(addToast({ message: 'Đã lưu đánh giá chuyên gia', type: 'success' }));
      setManagementAnalysisDirty(false);
      return true;
    } catch (error: unknown) {
      dispatch(addToast({ message: error instanceof Error ? error.message : 'Lỗi lưu đánh giá', type: 'error' }));
      return false;
    }
  };

  const handleSaveAnalysis = async () => {
    if (!id) return;
    const saveOrder =
      activeTab === TabIds.ManagementAnalysis
        ? [saveManagementAnalysisSection, saveStaffAnalysisSection]
        : [saveStaffAnalysisSection, saveManagementAnalysisSection];

    for (const saveSection of saveOrder) {
      const ok = await saveSection();
      if (!ok) return;
    }
  };

  const dismissStaffAnalysisErrors = () => {
    setStaffAnalysisErrors({});
    setStaffBannerCollapsed(false);
  };

  const dismissManagementAnalysisErrors = () => {
    setManagementAnalysisErrors({});
    setManagementBannerCollapsed(false);
  };

  const handleCancelAnalysis = () => {
    if (!selectedIncident) return;
    if (staffAnalysisDirty) {
      setForm((prev) => ({ ...prev, staffAnalysis: mergeStaffAnalysis(selectedIncident.staffAnalysis) }));
      setStaffAnalysisDirty(false);
      dismissStaffAnalysisErrors();
    }
    if (managementAnalysisDirty) {
      setForm((prev) => ({ ...prev, managementAnalysis: mergeManagementAnalysis(selectedIncident.managementAnalysis) }));
      setManagementAnalysisDirty(false);
      dismissManagementAnalysisErrors();
    }
  };

  if (loading && !isNew) {
    return (
      <div className={styles.loadingWrap}>
        <i className="fas fa-spinner fa-spin" /> Đang tải...
      </div>
    );
  }

  const mainTabs = [
    { id: TabIds.Incident,           label: 'Sự Cố Y Khoa',       icon: 'fas fa-hospital-user' },
    ...(!isNew ? [
      { id: TabIds.StaffAnalysis,      label: 'Phân Tích Sự Cố',    icon: 'fas fa-search'        },
      { id: TabIds.ManagementAnalysis, label: 'Chuyên Gia Đánh Giá', icon: 'fas fa-user-tie'      },
      { id: TabIds.Chat,               label: 'Trao Đổi',            icon: 'fas fa-comments', badge: chatCount, badgeColor: 'primary' as const },
    ] : []),
    { id: TabIds.Documents,          label: 'Tài Liệu / Bằng Chứng', icon: 'fas fa-paperclip'     },
  ];

  // Feedback section visible when owner + resolved/closed
  const showFeedbackSection =
    !isNew &&
    (form.status === IncidentStatus.Resolved || form.status === IncidentStatus.Closed) &&
    form.createdById === authUser?.id;

  const hasErrors = Object.keys(validationErrors).length > 0;

  // ── Derived flags for button visibility and read-only ──────────────────
  // Service-mismatch / not-medical-incident reports skip analysis workflow
  const isMismatchReport = !!(form.isServiceMismatch || form.isNotMedicalIncident);
  // Resolved / Closed — read-only unless user has edit-when-complete permission
  const isCompleteStatus =
    form.status === IncidentStatus.Resolved || form.status === IncidentStatus.Closed;

  // Tab 1 (incident info): editable only if owner AND still in pre-analysis state,
  // OR manager/admin with edit-when-complete on resolved/closed.
  const isOwner = isNew ||
    form.createdById === authUser?.id ||
    (!!form.reportedById && form.reportedById === authUser?.id);
  const isPreAnalysis = isNew ||
    form.status === IncidentStatus.Draft ||
    form.status === IncidentStatus.Submitted;
  const isTab1ReadOnly = isCompleteStatus
    ? !canEditWhenComplete
    : (isNew && !canCreate) ||
      (isMismatchReport && !isNew && form.status !== IncidentStatus.Draft && !isOwner) ||
      (!isNew && !(isOwner && isPreAnalysis));


  // Tab 4 (analysis): in_analysis + save-analysis, OR complete + edit-when-complete
  const canEditAnalysisTab =
    (canSaveAnalysis && form.status === IncidentStatus.InAnalysis) ||
    (canEditWhenComplete && isCompleteStatus);
  const isAnalysisReadOnly = !canEditAnalysisTab;

  // Legacy alias kept for the draft/submit button visibility logic below
  const isReadOnly = isTab1ReadOnly;

  // Analysis tab dirty/edit-mode derived flags
  const isAnalysisTab = activeTab === TabIds.StaffAnalysis || activeTab === TabIds.ManagementAnalysis;
  const analysisDirty = staffAnalysisDirty || managementAnalysisDirty;
  const showAnalysisEditMode = !isAnalysisReadOnly && analysisDirty;
  const analysisSaveLabel =
    staffAnalysisDirty && managementAnalysisDirty
      ? 'Lưu phân tích & đánh giá'
      : staffAnalysisDirty
        ? 'Lưu phân tích'
        : 'Lưu đánh giá';

  const hasHeaderActions =
    showAnalysisEditMode ||
    showFeedbackSection ||
    (canEditWhenComplete && isCompleteStatus && formDirty && activeTab === TabIds.Incident) ||
    (canToggleMismatch && !isNew && !isCompleteStatus && form.status !== IncidentStatus.Draft) ||
    (canToggleNotMedical && !isNew && !isCompleteStatus && form.status !== IncidentStatus.Draft) ||
    (canStartAnalysis && !isNew && form.status === IncidentStatus.Submitted && !isMismatchReport) ||
    (canCompleteAnalysis && !isNew && form.status === IncidentStatus.InAnalysis && !isMismatchReport) ||
    (canSaveDraft && !isReadOnly && (isNew || form.status === IncidentStatus.Draft)) ||
    (canSubmitReport && !isReadOnly && (isNew || form.status === IncidentStatus.Draft)) ||
    (canSubmitReport && !isReadOnly && !isNew && form.status === IncidentStatus.Submitted) ||
    (canPrint && !isNew && !!form.status && form.status !== IncidentStatus.Draft);

  const statusHint = resolveIncidentFormHint({
    isNew,
    status: form.status,
    activeTab: activeTab as IncidentFormTabId,
    isTab1ReadOnly,
    isAnalysisReadOnly,
    isAnalysisTab,
    isMismatchReport,
    hasHeaderActions,
    canSubmitReport,
    canStartAnalysis,
    canSaveAnalysis,
    canEditWhenComplete,
    showFeedbackSection,
    hasStaffFeedback: !!form.staffFeedbackAt,
    isOwner,
  });

  // ── Status badge ─────────────────────────────────────────────────────
  const statusLabelMap: Record<string, string> = {
    [IncidentStatus.Draft]:      'Nháp',
    [IncidentStatus.Submitted]:  'Đã gửi',
    [IncidentStatus.InAnalysis]: 'Đang phân tích',
    [IncidentStatus.Resolved]:   'Đã hoàn thành',
    [IncidentStatus.Closed]:     'Đã đóng',
  };
  const statusClassMap: Record<string, string> = {
    [IncidentStatus.Draft]:      styles.statusDraft,
    [IncidentStatus.Submitted]:  styles.statusSubmitted,
    [IncidentStatus.InAnalysis]: styles.statusAnalysis,
    [IncidentStatus.Resolved]:   styles.statusResolved,
    [IncidentStatus.Closed]:     styles.statusClosed,
  };

  return (
    <div className={styles.page}>
      {/* ── Sticky band: header + tabs ─────────────────────────────────── */}
      <div className={styles.stickyTop}>
        {/* Page header */}
        <div className={styles.pageHeader}>
          <div className={styles.titleGroup}>
            <button className={styles.backBtn} onClick={handleBack}>
              <i className="fas fa-arrow-left" />
            </button>
            <div>
              <div className={styles.titleRow}>
                <h1 className={styles.title}>
                  {isNew ? 'Thêm sự cố y khoa mới' : `Sự cố: ${form.idCode || '...'}`}
                </h1>
                {!isNew && form.status && (
                  <span className={`${styles.statusBadge} ${statusClassMap[form.status] ?? ''}`}>
                    {statusLabelMap[form.status] ?? form.status}
                  </span>
                )}
                {!isNew && form.isServiceMismatch && (
                  <span className={`${styles.statusBadge} ${styles.statusMismatch}`}>
                    <i className="fas fa-exchange-alt" /> Nhầm Dịch Vụ
                  </span>
                )}
                {!isNew && form.isNotMedicalIncident && (
                  <span className={`${styles.statusBadge} ${styles.statusNotMedical}`}>
                    <i className="fas fa-ban" /> Nhầm Sự Cố
                  </span>
                )}
              </div>
              {!isNew && form.incidentName && (
                <p className={styles.subtitle}>{form.incidentName}</p>
              )}
            </div>
          </div>
          <div className={styles.headerActions}>
            {/* ── Analysis edit mode: dirty state → show only Save + Cancel ── */}
            {showAnalysisEditMode ? (
              <>
                <Button variant="secondary" onClick={handleCancelAnalysis} disabled={saving}>
                  <i className="fas fa-times" /> Hủy
                </Button>
                <Button variant="primary" onClick={handleSaveAnalysis} disabled={saving}>
                  {saving
                    ? <><i className="fas fa-spinner fa-spin" /> Đang lưu...</>
                    : <><i className="fas fa-save" /> {analysisSaveLabel}</>
                  }
                </Button>
              </>
            ) : (
              <>
                {/* Feedback button/badge — owner + resolved/closed */}
                {showFeedbackSection && (
                  form.staffFeedbackAt ? (
                    <button className={styles.feedbackBadge} onClick={() => setFeedbackOpen(true)} title="Xem chi tiết đánh giá">
                      <i className="fas fa-check-circle" />
                      {[1,2,3,4,5].map((s) => (
                        <i key={s} className="fas fa-star" style={{ color: s <= (form.staffRating ?? 0) ? '#f59e0b' : '#d1d5db', fontSize: 12 }} />
                      ))}
                      <span>{form.staffRating}/5</span>
                      {form.staffFeedback && (
                        <span className={styles.feedbackBadgeText}>
                          — {form.staffFeedback.length > 30 ? form.staffFeedback.slice(0, 30) + '…' : form.staffFeedback}
                        </span>
                      )}
                    </button>
                  ) : (
                    <Button variant="warning" onClick={() => setFeedbackOpen(true)}>
                      <i className="fas fa-star" /> Đánh giá
                    </Button>
                  )
                )}
                {/* Service mismatch toggle — manager workflow (:write) */}
                {canToggleMismatch && !isNew && !isCompleteStatus && form.status !== IncidentStatus.Draft && (
                  <Button
                    variant={form.isServiceMismatch ? 'danger' : 'secondary'}
                    onClick={handleToggleServiceMismatch}
                    disabled={saving}
                  >
                    <i className={`fas ${form.isServiceMismatch ? 'fa-times-circle' : 'fa-exchange-alt'}`} />
                    {form.isServiceMismatch ? ' Bỏ nhầm DV' : ' Nhầm dịch vụ'}
                  </Button>
                )}
                {canToggleNotMedical && !isNew && !isCompleteStatus && form.status !== IncidentStatus.Draft && (
                  <Button
                    variant={form.isNotMedicalIncident ? 'danger' : 'secondary'}
                    onClick={handleToggleNotMedicalIncident}
                    disabled={saving}
                  >
                    <i className={`fas ${form.isNotMedicalIncident ? 'fa-times-circle' : 'fa-ban'}`} />
                    {form.isNotMedicalIncident ? ' Bỏ nhầm SC' : ' Nhầm sự cố'}
                  </Button>
                )}
                {canStartAnalysis && !isNew && form.status === IncidentStatus.Submitted && !isMismatchReport && (
                  <Button variant="warning" onClick={handleStartAnalysis} disabled={saving}>
                    <i className="fas fa-play" /> Bắt đầu phân tích
                  </Button>
                )}
                {canCompleteAnalysis && !isNew && form.status === IncidentStatus.InAnalysis && !isMismatchReport && (
                  <Button variant="success" onClick={handleSubmitAnalysis} disabled={saving}>
                    <i className="fas fa-check" /> Đánh dấu hoàn thành
                  </Button>
                )}
                {canSaveDraft && !isReadOnly && (isNew || form.status === IncidentStatus.Draft) && (
                  <Button variant="secondary" onClick={() => handleSave(true)} disabled={saving}>
                    <i className="fas fa-save" /> Lưu nháp
                  </Button>
                )}
                {canSubmitReport && !isReadOnly && (isNew || form.status === IncidentStatus.Draft) && (
                  <Button variant="primary" onClick={() => handleSave(false)} disabled={saving}>
                    {saving
                      ? <><i className="fas fa-spinner fa-spin" /> Đang lưu...</>
                      : <><i className="fas fa-paper-plane" /> Gửi báo cáo</>
                    }
                  </Button>
                )}
                {canSubmitReport && !isReadOnly && !isNew && form.status === IncidentStatus.Submitted && (
                  <Button variant="primary" onClick={() => handleSave(false)} disabled={saving}>
                    {saving
                      ? <><i className="fas fa-spinner fa-spin" /> Đang lưu...</>
                      : <><i className="fas fa-save" /> Cập nhật</>
                    }
                  </Button>
                )}
                {canEditWhenComplete && isCompleteStatus && formDirty && activeTab === TabIds.Incident && (
                  <Button variant="primary" onClick={() => handleSave(false)} disabled={saving}>
                    {saving
                      ? <><i className="fas fa-spinner fa-spin" /> Đang lưu...</>
                      : <><i className="fas fa-save" /> Cập nhật</>
                    }
                  </Button>
                )}
                {canPrint && !isNew && form.status && form.status !== IncidentStatus.Draft && (
                  <Button variant="secondary" onClick={() => setPrintModalOpen(true)}>
                    <i className="fas fa-file-pdf" /> Tải PDF
                  </Button>
                )}
              </>
            )}
          </div>
        </div>

        {/* Main tabs */}
        <div className={styles.tabsWrapper}>
          <Tabs
            tabs={mainTabs}
            activeTab={activeTab}
            onTabChange={(tab) => {
              setActiveTab(tab as TabIds);
              if (tab === TabIds.Incident) {
                setValidationErrors({});
              }
              // Dismiss analysis validation banners when leaving those tabs
              if (tab !== TabIds.StaffAnalysis) {
                dismissStaffAnalysisErrors();
              }
              if (tab !== TabIds.ManagementAnalysis) {
                dismissManagementAnalysisErrors();
              }
            }}
            variant="default"
          />
        </div>
        {statusHint && !showAnalysisEditMode && !(hasErrors && activeTab === TabIds.Incident) && (
          <div
            className={
              statusHint.variant === 'readonly'
                ? `${styles.hintBanner} ${styles.hintBannerReadonly}`
                : `${styles.hintBanner} ${styles.hintBannerGuide}`
            }
          >
            <p className={styles.hintBannerText}>
              <i className={statusHint.icon} />
              {statusHint.message}
            </p>
            {statusHint.actionLabel && statusHint.actionTab && (
              <button
                type="button"
                className={styles.hintBannerAction}
                onClick={() => setActiveTab(statusHint.actionTab as TabIds)}
              >
                {statusHint.actionLabel}
              </button>
            )}
          </div>
        )}
        {/* ── Validation error banner (inside sticky so always visible) ── */}
        {hasErrors && activeTab === TabIds.Incident && (
          <div className={styles.errorBanner}>
            <i className="fas fa-exclamation-circle" />
            <div className={styles.errorBannerBody}>
              <div className={styles.errorBannerHeader}>
                <strong>
                  Vui lòng điền đầy đủ các trường bắt buộc:
                </strong>
                <div className={styles.errorBannerActions}>
                  <button
                    type="button"
                    className={styles.errorBannerToggle}
                    onClick={() => setBannerCollapsed((c) => !c)}
                    aria-label={bannerCollapsed ? 'Mở rộng' : 'Thu gọn'}
                    title={bannerCollapsed ? 'Mở rộng' : 'Thu gọn'}
                  >
                    <i className={`fas fa-chevron-${bannerCollapsed ? 'down' : 'up'}`} />
                    {bannerCollapsed ? `${Object.keys(validationErrors).length} lỗi` : 'Thu gọn'}
                  </button>
                  <button
                    type="button"
                    className={styles.errorBannerClose}
                    onClick={() => setValidationErrors({})}
                    aria-label="Đóng"
                    title="Ẩn thông báo lỗi"
                  >
                    <i className="fas fa-times" />
                  </button>
                </div>
              </div>
              {!bannerCollapsed && (
                <ul>
                  {Object.values(validationErrors).map((msg, i) => (
                    <li key={i}>{msg}</li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        )}
        {/* ── Analysis error banner (staff / management tabs) ── */}
        {activeTab === TabIds.StaffAnalysis && Object.keys(staffAnalysisErrors).length > 0 && (
          <div className={styles.errorBanner}>
            <i className="fas fa-exclamation-circle" />
            <div className={styles.errorBannerBody}>
              <div className={styles.errorBannerHeader}>
                <strong>Vui lòng điền đầy đủ các trường bắt buộc:</strong>
                <div className={styles.errorBannerActions}>
                  <button
                    type="button"
                    className={styles.errorBannerToggle}
                    onClick={() => setStaffBannerCollapsed((c) => !c)}
                    aria-label={staffBannerCollapsed ? 'Mở rộng' : 'Thu gọn'}
                    title={staffBannerCollapsed ? 'Mở rộng' : 'Thu gọn'}
                  >
                    <i className={`fas fa-chevron-${staffBannerCollapsed ? 'down' : 'up'}`} />
                    {staffBannerCollapsed ? `${Object.keys(staffAnalysisErrors).length} lỗi` : 'Thu gọn'}
                  </button>
                  <button
                    type="button"
                    className={styles.errorBannerClose}
                    onClick={dismissStaffAnalysisErrors}
                    aria-label="Đóng"
                    title="Ẩn thông báo lỗi"
                  >
                    <i className="fas fa-times" />
                  </button>
                </div>
              </div>
              {!staffBannerCollapsed && (
                <ul>
                  {Object.values(staffAnalysisErrors).map((msg, i) => (
                    <li key={i}>{msg}</li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        )}
        {activeTab === TabIds.ManagementAnalysis && Object.keys(managementAnalysisErrors).length > 0 && (
          <div className={styles.errorBanner}>
            <i className="fas fa-exclamation-circle" />
            <div className={styles.errorBannerBody}>
              <div className={styles.errorBannerHeader}>
                <strong>Vui lòng điền đầy đủ các trường bắt buộc:</strong>
                <div className={styles.errorBannerActions}>
                  <button
                    type="button"
                    className={styles.errorBannerToggle}
                    onClick={() => setManagementBannerCollapsed((c) => !c)}
                    aria-label={managementBannerCollapsed ? 'Mở rộng' : 'Thu gọn'}
                    title={managementBannerCollapsed ? 'Mở rộng' : 'Thu gọn'}
                  >
                    <i className={`fas fa-chevron-${managementBannerCollapsed ? 'down' : 'up'}`} />
                    {managementBannerCollapsed ? `${Object.keys(managementAnalysisErrors).length} lỗi` : 'Thu gọn'}
                  </button>
                  <button
                    type="button"
                    className={styles.errorBannerClose}
                    onClick={dismissManagementAnalysisErrors}
                    aria-label="Đóng"
                    title="Ẩn thông báo lỗi"
                  >
                    <i className="fas fa-times" />
                  </button>
                </div>
              </div>
              {!managementBannerCollapsed && (
                <ul>
                  {Object.values(managementAnalysisErrors).map((msg, i) => (
                    <li key={i}>{msg}</li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        )}
      </div>

      {/* ── Tab content ───────────────────────────────────────────────── */}
      <div className={styles.tabContent}>
        {/* Tab 1: Sự Cố Y Khoa */}
        {activeTab === TabIds.Incident && (
          <Tab1IncidentInfo
            form={form}
            onChange={patch}
            isNew={isNew}
            readOnly={isTab1ReadOnly}
            errors={validationErrors}
          />
        )}

        {/* Tab 2: Phân Tích Sự Cố — dành cho nhân viên chuyên trách */}
        {activeTab === TabIds.StaffAnalysis && form.staffAnalysis && (
          <Tab4AStaffAnalysis
            data={form.staffAnalysis}
            onChange={(p) => {
              patch({ staffAnalysis: { ...form.staffAnalysis!, ...p } });
              setStaffAnalysisDirty(true);
              setStaffAnalysisErrors((prev) => {
                const next = { ...prev };
                Object.keys(p).forEach((k) => delete next[k]);
                return next;
              });
            }}
            readOnly={isAnalysisReadOnly}
            errors={staffAnalysisErrors}
            incidentStatus={form.status}
            incidentDepartmentLocation={form.incidentDepartmentLocation ?? ''}
            incidentSubjects={{
              subjectPatient:   form.subjectPatient   ?? false,
              subjectStaff:     form.subjectStaff     ?? false,
              subjectVisitor:   form.subjectVisitor   ?? false,
              subjectEquipment: form.subjectEquipment ?? false,
            } satisfies IncidentSubjects}
          />
        )}

        {/* Tab 3: Chuyên Gia Đánh Giá — dành cho cấp quản lý */}
        {activeTab === TabIds.ManagementAnalysis && form.managementAnalysis && (
          <Tab4BManagementAnalysis
            data={form.managementAnalysis}
            onChange={(p) => {
              patch({ managementAnalysis: { ...form.managementAnalysis!, ...p } });
              setManagementAnalysisDirty(true);
              setManagementAnalysisErrors((prev) => {
                const next = { ...prev };
                Object.keys(p).forEach((k) => delete next[k]);
                return next;
              });
            }}
            readOnly={isAnalysisReadOnly}
            errors={managementAnalysisErrors}
          />
        )}

        {/* Tab 4: Trao đổi (chat) — only shown when incident exists */}
        {activeTab === TabIds.Chat && !isNew && (
          <div className={styles.tabSection}>
            <ChatTab
              entityId={id!}
              entityType="incident"
              messages={chatMessages}
              currentUserId={authUser?.id}
              onSendMessage={sendMessage}
              loading={chatLoading}
              hasMore={hasMoreChat}
              onLoadMore={loadMoreChat}
            />
          </div>
        )}

        {/* Tab 5: Tài Liệu / Bằng Chứng */}
        {activeTab === TabIds.Documents && (
          <div className={styles.emptyTab}>
            <i className="fas fa-paperclip" />
            <h3>Tài Liệu / Bằng Chứng</h3>
            <p>Chức năng đính kèm tài liệu và bằng chứng giải quyết sẽ được triển khai trong phiên bản tiếp theo.</p>
          </div>
        )}
      </div>

      {/* ── Feedback slide-out panel ────────────────────────────────── */}
      {feedbackOpen && (
        <>
          <div className={styles.slideOverlay} onClick={() => setFeedbackOpen(false)} />
          <div className={styles.slidePanel}>
            <div className={styles.slidePanelHeader}>
              <h2><i className="fas fa-star" /> {form.staffFeedbackAt ? 'Chi Tiết Đánh Giá' : 'Đánh Giá Kết Quả Giải Quyết'}</h2>
              <button className={styles.slidePanelClose} onClick={() => setFeedbackOpen(false)} aria-label="Đóng">
                <i className="fas fa-times" />
              </button>
            </div>

            {form.staffFeedbackAt ? (
              /* ── Read-only detail view ── */
              <div className={styles.slidePanelBody}>
                <div className={styles.feedbackDetailRow}>
                  <span className={styles.feedbackDetailLabel}>Đánh giá</span>
                  <div className={styles.feedbackDetailStars}>
                    {[1,2,3,4,5].map((s) => (
                      <i key={s} className="fas fa-star" style={{ color: s <= (form.staffRating ?? 0) ? '#f59e0b' : '#d1d5db' }} />
                    ))}
                    <span className={styles.feedbackDetailRating}>{form.staffRating}/5</span>
                  </div>
                </div>
                {form.staffFeedback && (
                  <div className={styles.feedbackDetailRow}>
                    <span className={styles.feedbackDetailLabel}>Nhận xét</span>
                    <p className={styles.feedbackDetailComment}>{form.staffFeedback}</p>
                  </div>
                )}
                <div className={styles.feedbackDetailRow}>
                  <span className={styles.feedbackDetailLabel}>Ngày đánh giá</span>
                  <span className={styles.feedbackDetailValue}>
                    {new Date(form.staffFeedbackAt).toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ) : (
              /* ── Editable form ── */
              <>
                <div className={styles.slidePanelBody}>
                  <p className={styles.feedbackHint}>Vui lòng chọn số sao và nhập nhận xét (tùy chọn) để hoàn tất đánh giá.</p>
                  <div className={styles.feedbackStarPicker}>
                    {[1,2,3,4,5].map((s) => (
                      <button
                        key={s}
                        className={styles.starBtn}
                        onClick={() => setFeedbackRating(s)}
                        aria-label={`${s} sao`}
                      >
                        <i className="fas fa-star" style={{ color: s <= feedbackRating ? '#f59e0b' : '#d1d5db' }} />
                      </button>
                    ))}
                  </div>
                  <textarea
                    className={styles.feedbackTextarea}
                    placeholder="Nhận xét của bạn (tùy chọn)..."
                    value={feedbackText}
                    onChange={(e) => setFeedbackText(e.target.value)}
                    rows={4}
                  />
                </div>
                <div className={styles.slidePanelFooter}>
                  <Button variant="secondary" onClick={() => setFeedbackOpen(false)}>Hủy</Button>
                  <Button variant="primary" onClick={handleSubmitFeedback} disabled={saving || feedbackRating < 1}>
                    {saving ? <><i className="fas fa-spinner fa-spin" /> Đang gửi...</> : <><i className="fas fa-paper-plane" /> Gửi đánh giá</>}
                  </Button>
                </div>
              </>
            )}
          </div>
        </>
      )}

      {/* ── PDF print modal ───────────────────────────────────────── */}
      {!isNew && form.id && (
        <IncidentPrintModal
          isOpen={printModalOpen}
          onClose={() => setPrintModalOpen(false)}
          incident={form as MedicalIncident}
        />
      )}

      <LeaveConfirmModal {...leaveConfirmModalProps} />
    </div>
  );
};

export default MedicalIncidentFormPage;
